28	
29				path = SanitizerModule.SanitizePath(this, path);
30	
31				LogFunction(nameof(DirectoryExists), new object[] { path });
32	
33				// quickly check if root path, then it always exists!
34				if (path.IsFtpRootDirectory()) {
35					return true;
36				}
37	
38				// If PreserveTrailingSlashCmdList enabled for CWD... but: Don't do it for root dir and any
39				// directories that already end with a slash (which shouldn't happen, but let's be safe)
40				if (Config.PreserveTrailingSlashCmdList != null && Config.PreserveTrailingSlashCmdList.Contains("CWD") && !path.EndsWith("/")) {
41					path += "/";
42				}
43	
44				// check if a folder exists by changing the working dir to it
45				pwd = GetWorkingDirectory();
46	
47				// If PreserveTrailingSlashCmdList enabled for CWD... but: Don't do it for root dir and any
48				// directories that already end with a slash (which shouldn't happen, but let's be safe)
49				if (Config.PreserveTrailingSlashCmdList != null && Config.PreserveTrailingSlashCmdList.Contains("CWD") && !pwd.EndsWith("/")) {
50					pwd += "/";
51				}
52	
53				if (Execute("CWD " + path).Success) {
54					var reply = Execute("CWD " + pwd);
55	
56					if (!reply.Success) {
57						throw new FtpException("DirectoryExists(): Failed to restore the working directory.");
58					}
