84	
85				if (!IsConnected) {
86					throw new InvalidOperationException("No connection to the server has been established.");
87				}
88	
89				stream.ReadTimeout = Config.ReadTimeout;
90				stream.WriteTimeout = Config.WriteTimeout;
91				while ((buf = await stream.ReadLineAsync(Encoding, token)) != null) {
92					Match m;
93	
94					Log(FtpTraceLevel.Info, buf);
95	
96					if ((m = Regex.Match(buf, @"^HTTP/.*\s(?<code>[0-9]{3}) (?<message>.*)$")).Success) {
97						reply.Code = m.Groups["code"].Value;
98						reply.Message = m.Groups["message"].Value;
99						break;
100					}
101	
102					reply.InfoMessages += buf + "\n";
103				}
104	
105				// fixes #84 (missing bytes when downloading/uploading files through proxy)
106				while ((buf = await stream.ReadLineAsync(Encoding, token)) != null) {
107					Log(FtpTraceLevel.Info, buf);
108	
109					if (Strings.IsNullOrWhiteSpace(buf)) {
110						break;
111					}
112	
113					reply.InfoMessages += buf + "\n";
114				}
115	
116				return reply;
